-- Entra security group object id -> entity code (PostgreSQL).
-- Prefer Liquibase changeSet 016-entra-guid-entity-map (schema + seed under db/changelog).
-- This script is for manual / one-off loads: truncates then bulk inserts.
-- Regenerate from CSV: name, guid, entity columns (see GroupCreationResult export).

CREATE TABLE IF NOT EXISTS entra_guid_entity_map (
    id BIGSERIAL PRIMARY KEY,
    guid VARCHAR(36) NOT NULL,
    entity_code VARCHAR(64) NOT NULL,
    display_name VARCHAR(512),
    CONSTRAINT uq_entra_guid_entity_map_guid UNIQUE (guid)
);

CREATE INDEX IF NOT EXISTS idx_entra_guid_entity_map_guid_lower ON entra_guid_entity_map (LOWER(guid));

TRUNCATE TABLE entra_guid_entity_map RESTART IDENTITY CASCADE;

